const CACHE='margin-v13';
const ASSETS=['/','/index.html','/app.js','/engine.js','/network-planner.js','/scenarios.js','/service-alerts.js','/service-check.js','/live-plan.js','/trip-summary.js','/crowding.js','/journey-enrichment.js','/routines.js','/location.js','/data/network.js','/style.css','/mobile.css','/manifest.webmanifest','/icon-192.png','/icon-512.png','/data/osm-roads.json'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS)).then(()=>self.skipWaiting()));});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('margin-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin||!ASSETS.includes(url.pathname))return;event.respondWith(fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();event.waitUntil(caches.open(CACHE).then(cache=>cache.put(event.request,copy)));}return response;}).catch(()=>caches.match(event.request)));});
self.addEventListener('periodicsync',event=>{if(event.tag!=='margin-disruption-check')return;event.waitUntil((async()=>{try{const response=await fetch('/api/lta/train-alerts',{cache:'no-store'}),data=await response.json();if(response.ok&&data.source==='live'&&data.status==='disrupted'){const message=data.messages?.[0]?.content||'LTA reports a train service disruption. Open Margin to check your route.';await self.registration.showNotification('Train disruption reported',{body:message,icon:'/icon-192.png',badge:'/icon-192.png',tag:'margin-live-disruption',data:{url:'/'}});}}catch{}})());});
self.addEventListener('notificationclick',event=>{event.notification.close();event.waitUntil(clients.matchAll({type:'window',includeUncontrolled:true}).then(windows=>{for(const client of windows)if('focus'in client)return client.focus();return clients.openWindow(event.notification.data?.url||'/');}));});
